```verilog
module sync_fifo #(parameter WIDTH = 8, parameter DEPTH = 4)
  (input clk, input rst_n,
   input wr_en, input [WIDTH-1:0] din,
   input rd_en, output reg [WIDTH-1:0] dout,
   output full, output empty);

  localparam PTR_W  = $clog2(DEPTH) + 1;
  localparam ADDR_W = ($clog2(DEPTH) > 0) ? $clog2(DEPTH) : 1;

  reg [WIDTH-1:0] mem [0:DEPTH-1];
  reg [PTR_W-1:0] wr_ptr, rd_ptr;

  wire [ADDR_W-1:0] waddr;
  wire [ADDR_W-1:0] raddr;

  // Pointers are PTR_W bits wide (one extra MSB). When the pointers are equal
  // the FIFO is empty; when they are equal except for the MSB it is full.
  assign empty = (wr_ptr == rd_ptr);
  assign full  = (wr_ptr == (rd_ptr ^ (1'b1 << (PTR_W-1))));

  assign waddr = wr_ptr[ADDR_W-1:0] & (DEPTH-1);
  assign raddr = rd_ptr[ADDR_W-1:0] & (DEPTH-1);

  wire do_write = wr_en & ~full;
  wire do_read  = rd_en & ~empty;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      wr_ptr <= {PTR_W{1'b0}};
      rd_ptr <= {PTR_W{1'b0}};
      dout   <= {WIDTH{1'b0}};
    end else begin
      if (do_write) begin
        mem[waddr] <= din;
        wr_ptr <= wr_ptr + 1'b1;
      end
      if (do_read) begin
        dout   <= mem[raddr];
        rd_ptr <= rd_ptr + 1'b1;
      end
    end
  end

endmodule
```

message.reasoning:
Write a synchronous FIFO with pointer comparison using an extra bit (pointer width = log2(DEPTH)+1) to distinguish full/empty. DEPTH power of two, so pointer wrap naturally with extra bit.

Standard design: wr_ptr, rd_ptr of $clog2(DEPTH)+1 bits. full when pointers equal but MSB differs; empty when pointers fully equal.

DEPTH=4 default: pointer 3 bits.

